  ?p a brick:ElectricPower .
  ?p ref:hasName ?name .
  ?p ref:hasTimeseriesId ?ts .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
}

SELECT ?s ?p ?o WHERE {
  ?p2 ref:hasName ?name .
  FILTER(?name IN ("Chiller02","CondPump01","CondPump02"))
  ?p2 ?p ?o .
} LIMIT 200

SELECT ?s ?type ?ts WHERE {
  ?s rdfs:label ?lbl .
  FILTER(?lbl IN ("Chiller02","CondPump01","CondPump02"))
  OPTIONAL { ?s a ?type }
  OPTIONAL { ?s ref:hasTimeseriesId ?ts }
}

SELECT ?s ?ts WHERE {
  ?s ref:hasTimeseriesId ?ts .
  FILTER(STR(?s) LIKE "%Chiller02_Electric_Power_Sensor%" || STR(?s) LIKE "%CondPump01_Electric_Power_Sensor%" || STR(?s) LIKE "%CondPump02_Electric_Power_Sensor%")
}

SELECT ?s ?ts ?lbl WHERE {
  ?s ref:hasTimeseriesId ?ts .
  ?s rdfs:label ?lbl .
  FILTER(STRCONTAINS(STR(?s), "Chiller02") || STRCONTAINS(STR(?s), "CondPump01") || STRCONTAINS(STR(?s), "CondPump02"))
}

SELECT ?s ?ts ?lbl WHERE {
  ?s ref:hasTimeseriesId ?ts .
  ?s rdfs:label ?lbl .
  FILTER ( STRCONTAINS(STR(?s), "Chiller02") || STRCONTAINS(STR(?s), "CondPump01") || STRCONTAINS(STR(?s), "CondPump02") )
}

SELECT ?s ?ref WHERE {
  ?s ?p ?ref .
  FILTER( ?p = https://brickschema.org/schema/Brick/ref#hasExternalReference  )
