  FILTER( ?lbl IN ("CoolSys1 Chiller2","CoolSys1 Pump Secondary","HeatSys1 Pump") )
}

SELECT ?ref WHERE {
  ?s a brick:Electric_Power_Sensor .
  ?s ref:hasExternalReference ?ref .
  ?s rdfs:label ?lbl .
}

SELECT ?lbl ?ref WHERE {
